#!/bin/sh
# PreToolUse: block edits to secrets, lock files and generated files.
file=$(jq -r '.tool_input.file_path // empty')

case "$file" in
  */.env | */Cargo.lock | */pnpm-lock.yaml)
    echo "Blocked: $file is a secret or lock file. Change it outside Claude or via the package manager." >&2
    exit 2 ;;
  */api/src/db/schema.rs)
    echo "Blocked: schema.rs is generated. Add a migration in api/migrations/ and run diesel migration run." >&2
    exit 2 ;;
  */frontend/typed-router.d.ts)
    echo "Blocked: typed-router.d.ts is generated by unplugin-vue-router from src/pages/." >&2
    exit 2 ;;
esac
exit 0
